(function () { "use strict"; function boot() { var c = document.getElementById("background"); if (!c) return; var dpr = Math.max(1, window.devicePixelRatio || 1); var ctx = c.getContext("2d"); var W = 0, H = 0; var stars = []; function resize() { W = window.innerWidth; H = window.innerHeight; c.width = Math.floor(W * dpr); c.height = Math.floor(H * dpr); c.style.width = W + "px"; c.style.height = H + "px"; ctx.setTransform(dpr, 0, 0, dpr, 0, 0) } function rand(a, b) { return a + Math.random() * (b - a) } function init() { stars.length = 0; var n = Math.floor(Math.min(180, Math.max(60, W * H / 18000))); for (var i = 0; i < n; i++) { stars.push({ x: rand(0, W), y: rand(0, H), r: rand(0.6, 1.8), vx: rand(0.15, 0.45), vy: rand(0.25, 0.75), a: rand(0.15, 0.6) }) } } resize(); init(); window.addEventListener("resize", function () { resize(); init() }, { passive: true }); function draw() { ctx.clearRect(0, 0, W, H); ctx.save(); ctx.globalCompositeOperation = "lighter"; for (var i = 0; i < stars.length; i++) { var s = stars[i]; s.x += s.vx; s.y += s.vy; if (s.x > W + 20 || s.y > H + 20) { s.x = rand(-100, -20); s.y = rand(0, H * 0.6) } ctx.fillStyle = "rgba(255,255,255," + s.a + ")"; ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = "rgba(255,255,255," + (s.a * 0.35) + ")"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(s.x, s.y); ctx.lineTo(s.x - 18 * s.vx, s.y - 18 * s.vy); ctx.stroke() } ctx.restore(); requestAnimationFrame(draw) } draw() } if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot, { once: true }); else boot() })();
